SELECT s.s_store_name, d.d_year, SUM(ss.ss_ext_sales_price) AS total_sales, SUM(sr.sr_return_amt) AS total_returns, (SELECT sr2.sr_reason_sk FROM store_returns sr2 LIMIT 1) AS sample_return_reason FROM store_sales ss JOIN date_dim d ON ss.ss_sold_date_sk = d.d_date_sk JOIN store s ON ss.ss_store_sk = s.s_store_sk JOIN store_returns sr ON sr.sr_ticket_number = ss.ss_ticket_number GROUP BY s.s_store_name, d.d_year HAVING d.d_year = 1920
